import React, { useState } from 'react';
import axios from 'axios';
import './NewsScraper.css';

const NewsScraper = () => {
  const [url, setUrl] = useState('');
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('');

  const scrapeNews = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.post('http://localhost:5000/api/scrape', { url });
      setNews(response.data.news);
      setFilter(''); // Reset filter on new scrape
    } catch (err) {
      setError('Error scraping the website. Please try again.');
    }
    setLoading(false);
  };

  // Get unique subtopics/categories from the news data
  const uniqueCategories = Array.from(
    new Set(news.map(item => item.category).filter(Boolean))
  );

  const filteredAndSortedNews = news
    .filter(item => filter === '' || item.category === filter)
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  return (
    <div className="news-scraper">
      <h2 style={{textAlign: 'center', marginBottom: 24}}>Dynamic News Scraper</h2>
      <div className="controls">
        <input
          type="text"
          value={url}
          onChange={e => setUrl(e.target.value)}
          placeholder="Enter website URL to scrape"
          className="url-input"
        />
        <button
          onClick={scrapeNews}
          disabled={loading || !url}
          className="scrape-button"
        >
          {loading ? 'Scraping...' : 'Scrape News'}
        </button>
      </div>

      {news.length > 0 && (
        <div className="category-filters">
          <button
            className={`category-btn${filter === '' ? ' active' : ''}`}
            onClick={() => setFilter('')}
          >
            All
          </button>
          {uniqueCategories.map(cat => (
            <button
              key={cat}
              className={`category-btn${filter === cat ? ' active' : ''}`}
              onClick={() => setFilter(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
      )}

      {error && <div className="error">{error}</div>}

      {loading && (
        <div className="loading">
          <div className="spinner"></div>
          <p>Scraping in progress...</p>
        </div>
      )}

      <div className="news-list">
        {filteredAndSortedNews.length === 0 && news.length > 0 ? (
          <div style={{textAlign: 'center', width: '100%', color: '#888', fontSize: 18, marginTop: 40}}>
            No results found{filter ? ` for "${filter}"` : ''}.
          </div>
        ) : (
          filteredAndSortedNews.map((item, index) => (
            <div key={index} className="news-item">
              <h2>{item.headline}</h2>
              <div className="news-meta">
                <span>Category: {item.category || 'N/A'}</span>
                <span>Date: {item.date ? new Date(item.date).toLocaleString() : 'No date available'}</span>
                <span>Source: {item.source}</span>
              </div>
              <a href={item.url} target="_blank" rel="noopener noreferrer">
                Read More
              </a>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default NewsScraper;
